CREATE TABLE identity_identities(owner_id text PRIMARY KEY,address text NOT NULL UNIQUE,credential_id text NOT NULL,authority_hash text NOT NULL,sign_count bigint NOT NULL CHECK(sign_count>=0),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identity_challenges(id text PRIMARY KEY,address text NOT NULL,credential_id text NOT NULL,challenge_hash text NOT NULL,authority_hash text NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE identity_sessions(token_hash text PRIMARY KEY,owner_id text NOT NULL REFERENCES identity_identities(owner_id),authority_hash text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE INDEX identity_session_owner ON identity_sessions(owner_id);
CREATE TABLE resource_limits(key text PRIMARY KEY,used bigint NOT NULL CHECK(used>=0));
CREATE TABLE reservation_projects(id text PRIMARY KEY CHECK(id ~ '^[a-f0-9]{64}$'),owner_address text NOT NULL,revision integer NOT NULL DEFAULT 0 CHECK(revision>=0),data jsonb NOT NULL,approved_snapshot_id text);
CREATE TABLE reservation_media(id text PRIMARY KEY,project_id text NOT NULL REFERENCES reservation_projects(id),owner_address text NOT NULL,storage_key text NOT NULL UNIQUE,content_hash text NOT NULL,byte_size integer NOT NULL CHECK(byte_size BETWEEN 1 AND 2097152),state text NOT NULL CHECK(state IN ('STAGED','READY')),width integer NOT NULL CHECK(width BETWEEN 1 AND 2048),height integer NOT NULL CHECK(height BETWEEN 1 AND 2048),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reservation_snapshots(id text PRIMARY KEY,project_id text NOT NULL REFERENCES reservation_projects(id),revision integer NOT NULL,data jsonb NOT NULL,content_hash text NOT NULL,approved_at timestamptz NOT NULL,UNIQUE(project_id,revision));
CREATE TABLE reservation_offers(id text PRIMARY KEY,project_id text NOT NULL REFERENCES reservation_projects(id),snapshot_id text NOT NULL UNIQUE REFERENCES reservation_snapshots(id),state text NOT NULL CHECK(state IN ('PREPARING','AVAILABLE','UNCERTAIN','RESERVED','REJECTED')),holder text,published_at timestamptz,publish_hash text);
CREATE UNIQUE INDEX reservation_one_live_offer ON reservation_offers(project_id) WHERE state IN ('PREPARING','AVAILABLE','UNCERTAIN');
CREATE TABLE reservation_attempts(id text PRIMARY KEY,offer_id text NOT NULL REFERENCES reservation_offers(id),actor_address text NOT NULL,operation text NOT NULL CHECK(operation IN ('publish','reserve')),state text NOT NULL CHECK(state IN ('PREPARED','SUBMITTING','PENDING','NEEDS_RECONCILIATION','CONFIRMED','REJECTED','CONFLICT')),preparation jsonb,signed_payload jsonb,tx_hash text,receipt jsonb,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX reservation_active_attempt ON reservation_attempts(offer_id,actor_address,operation) WHERE state IN ('PREPARED','SUBMITTING','PENDING','NEEDS_RECONCILIATION');
CREATE TABLE reservation_messages(id text PRIMARY KEY,project_id text NOT NULL REFERENCES reservation_projects(id),role text NOT NULL CHECK(role IN ('user','assistant')),content jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gateway_budget_reservations(id text PRIMARY KEY,consumer text NOT NULL,owner_id text NOT NULL,day text NOT NULL,reserved_microusd bigint NOT NULL CHECK(reserved_microusd>=0),state text NOT NULL CHECK(state IN ('RESERVED','SENT','COMPLETED','UNKNOWN','RELEASED')),usage jsonb,created_at timestamptz NOT NULL DEFAULT now());
